import { resolve } from 'node:path';
import { getLocalPackageVersion } from '@sanity/cli-core/package-manager';
import { SANITY_INSTALLATION_CONFIG } from '../../constants.js';
/**
 * Stamps the installed `sanity` version onto each media-library config resource
 * before pre-deploy. The version is a label Brett stores on the config snapshot,
 * mirroring what `sanity deploy` sends for a media-library config; it is not what
 * the runtime loads. Other installation config types are left alone: the
 * media-library tie to the `sanity` package is specific to it.
 */
export const stampInstallationConfigVersion = async (resources, blueprintFileDir) => {
    for (const resource of resources) {
        if (resource.type !== SANITY_INSTALLATION_CONFIG)
            continue;
        const config = resource;
        if (config.appType !== 'media-library')
            continue;
        // Update values not included in the blueprint.
        if (config.version !== undefined)
            continue;
        const workDir = resolve(blueprintFileDir, config.root);
        const version = await getLocalPackageVersion('sanity', workDir);
        if (!version) {
            throw new Error(`Unable to determine the installed 'sanity' version for installation config resource '${config.name}'; is 'sanity' installed in '${config.root}'?`);
        }
        config.version = version;
    }
};
